def quota(nodes):
    return [{'id':n[0],'parent':n[1],'capacity':n[2]} for n in nodes]

# ---------------------------------------------------------------- plan oracle
def feasible(pairs, request_info, offer_info, rnodes, onodes, choice):
    """Is `choice` (set of (rid,oid)) a feasible assignment?"""
    used={}
    for rid,oid in choice:
        if rid in used: return False
        used[rid]=oid
        info=request_info[rid]; offer=offer_info[oid]
        if rid not in offer['reqs']: return False
        if offer['service']!=info['service']: return False
        if not (info['at']<=offer['time']<info['end']): return False
        if not (offer['lo']<=info['address']<=offer['hi']): return False
    counts={}
    for rid,oid in choice: counts[oid]=counts.get(oid,0)+1
    for oid,n in counts.items():
        if n>offer_info[oid]['capacity']: return False
    def consume(nodes,info):
        total={}
        for name,_,_ in nodes: total[name]=0
        node={n[0]:n for n in nodes}
        for rid,oid in choice:
            at=info[rid]['group']
            while at is not None:
                total[at]=total.get(at,0)+1
                at=node[at][1]
        return total
    left=consume(rnodes,request_info)
    for name,value in left.items():
        cap=dict((n[0],n[2]) for n in rnodes)
        if value>cap[name]: return False
    right=consume(onodes,offer_info)
    cap=dict((n[0],n[2]) for n in onodes)
    for name,value in right.items():
        if value>cap[name]: return False
    return True

def oracle(job, active):
    """Brute force optimum (cardinality, cost) for a tiny campaign."""
    request_info={}
    for rid,row in job['requests'].items():
        import ipaddress
        lease=[l for l in job['leases'] if l['id']==row['lease']][0]
        request_info[rid]={'at':row['at'],'service':row['service'],'group':row['group'],
                           'address':int(ipaddress.IPv6Address(row['target'])),
                           'end':lease['end']}
    offer_info={}
    for oid,row in job['offers'].items():
        import ipaddress
        net=ipaddress.IPv6Network(row['prefix'])
        offer_info[oid]={'time':row['time'],'service':row['service'],
                         'lo':int(net.network_address),'hi':int(net.broadcast_address),
                         'capacity':row['capacity'],'cost':row['cost'],
                         'reqs':set(row['requests'])}
    pairs=[(rid,oid) for oid,row in job['offers'].items() for rid in row['requests']
           if active.get(rid)]
    best=(0,0)
    for size in range(len(pairs),-1,-1):
        found=None
        for choice in itertools.combinations(pairs,size):
            if not feasible(set(),request_info,offer_info,job['request_quotas'],
                            job['offer_quotas'],choice):
                continue
            cost=sum(offer_info[oid]['cost'] for _,oid in choice)
            if found is None or cost<found: found=cost
        if found is not None:
            return (size,found)
    return (0,0)

def check_plan(job, result, active):
    """Validate the returned plan against the brute-force oracle."""
    assert set(result)=={'resolved','cost','assignments'}, result
    assignments=result['assignments']
    rids=[a['request'] for a in assignments]
    assert rids==sorted(rids), 'assignments not sorted'
    assert len(set(rids))==len(rids), 'duplicate request assignment'
    choice=[(a['request'],a['offer']) for a in assignments]
    request_info={}
    import ipaddress
    for rid,row in job['requests'].items():
        lease=[l for l in job['leases'] if l['id']==row['lease']][0]
        request_info[rid]={'at':row['at'],'service':row['service'],'group':row['group'],
                           'address':int(ipaddress.IPv6Address(row['target'])),
                           'end':lease['end']}
    offer_info={}
    for oid,row in job['offers'].items():
        net=ipaddress.IPv6Network(row['prefix'])
        offer_info[oid]={'time':row['time'],'service':row['service'],
                         'lo':int(net.network_address),'hi':int(net.broadcast_address),
                         'capacity':row['capacity'],'cost':row['cost'],
                         'reqs':set(row['requests'])}
    assert feasible(None,request_info,offer_info,job['request_quotas'],job['offer_quotas'],choice), \
        'returned plan is infeasible: '+repr(choice)
    cost=sum(offer_info[oid]['cost'] for _,oid in choice)
    assert cost==result['cost'], (cost,result['cost'])
    assert result['resolved']==len(assignments)
    want=oracle(job,active)
    assert (result['resolved'],result['cost'])==want, ((result['resolved'],result['cost']),want)
    # certificate shape
    for a in assignments:
